import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"44、【姤】 巽下乾上","description":"橫渠易說 - 44、【姤】 巽下乾上","frontmatter":{"title":"44、【姤】 巽下乾上","description":"橫渠易說 - 44、【姤】 巽下乾上"},"headers":[],"relativePath":"classics/hengqu/046.md","filePath":"classics/hengqu/046.md"}'),l={name:"classics/hengqu/046.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_44、【姤】-巽下乾上" tabindex="-1">44、【姤】 巽下乾上 <a class="header-anchor" href="#_44、【姤】-巽下乾上" aria-label="Permalink to “44、【姤】 巽下乾上”">​</a></h1><h3 id="彖曰-姤-遇也-柔遇剛也。-勿用取女-不可與長也。天地相遇-品物鹹章也-剛遇中正-天下大行也。姤之時義大矣哉" tabindex="-1">彖曰：姤，遇也，柔遇剛也。“勿用取女”，不可與長也。天地相遇，品物鹹章也，剛遇中正，天下大行也。姤之時義大矣哉! <a class="header-anchor" href="#彖曰-姤-遇也-柔遇剛也。-勿用取女-不可與長也。天地相遇-品物鹹章也-剛遇中正-天下大行也。姤之時義大矣哉" aria-label="Permalink to “彖曰：姤，遇也，柔遇剛也。“勿用取女”，不可與長也。天地相遇，品物鹹章也，剛遇中正，天下大行也。姤之時義大矣哉!”">​</a></h3><p>非中爻不能備卦德，故曰“剛遇中正”。</p><h3 id="象曰-天下有風-姤-後以施命誥四方。" tabindex="-1">象曰：天下有風，姤，後以施命誥四方。 <a class="header-anchor" href="#象曰-天下有風-姤-後以施命誥四方。" aria-label="Permalink to “象曰：天下有風，姤，後以施命誥四方。”">​</a></h3><p>上所以用柔於下者，誥令莫大焉。</p><h3 id="初六-繫於金柅-貞吉。有攸往-見兇。羸豕孚蹢躅。-象曰-繫於金柅-柔道牽也。" tabindex="-1">初六，繫於金柅，貞吉。有攸往，見兇。羸豕孚蹢躅。 象曰：“繫於金柅”，柔道牽也。 <a class="header-anchor" href="#初六-繫於金柅-貞吉。有攸往-見兇。羸豕孚蹢躅。-象曰-繫於金柅-柔道牽也。" aria-label="Permalink to “初六，繫於金柅，貞吉。有攸往，見兇。羸豕孚蹢躅。 象曰：“繫於金柅”，柔道牽也。”">​</a></h3><p>金柅二物也，處姤之時，不牽於近則所往皆兇。孚，信也。豕方羸時，力未能動，然至誠在於蹢躅，得申則申矣。如李德裕處置閹宦，徒知其帖息威伏，而忽於志不(忘)［妄］逞，照察少不至則失其幾也。</p><h3 id="九二-包有魚-無咎-不利賓。-象曰-包有魚-義不及賓也。" tabindex="-1">九二，包有魚，無咎，不利賓。 象曰：“包有魚”，義不及賓也。 <a class="header-anchor" href="#九二-包有魚-無咎-不利賓。-象曰-包有魚-義不及賓也。" aria-label="Permalink to “九二，包有魚，無咎，不利賓。 象曰：“包有魚”，義不及賓也。”">​</a></h3><h3 id="九三-臀無膚-其行次且-厲無大咎。-象曰-其行次且-行未牽也。" tabindex="-1">九三，臀無膚，其行次且，厲無大咎。 象曰：“其行次且”，行未牽也。 <a class="header-anchor" href="#九三-臀無膚-其行次且-厲無大咎。-象曰-其行次且-行未牽也。" aria-label="Permalink to “九三，臀無膚，其行次且，厲無大咎。 象曰：“其行次且”，行未牽也。”">​</a></h3><p>行而無所與遇，故曰“行未牽也”，進退無所繫也。</p><h3 id="九四-包無魚-起兇。-象曰-無魚之兇-遠民也。" tabindex="-1">九四，包無魚，起兇。 象曰：無魚之兇，遠民也。 <a class="header-anchor" href="#九四-包無魚-起兇。-象曰-無魚之兇-遠民也。" aria-label="Permalink to “九四，包無魚，起兇。 象曰：無魚之兇，遠民也。”">​</a></h3><h3 id="九五-以杞包瓜-含章-有隕自天。-象曰-九五含章-中正也。-有隕自天-志不捨命也。" tabindex="-1">九五，以杞包瓜，含章，有隕自天。 象曰：九五含章，中正也。“有隕自天”，志不捨命也。 <a class="header-anchor" href="#九五-以杞包瓜-含章-有隕自天。-象曰-九五含章-中正也。-有隕自天-志不捨命也。" aria-label="Permalink to “九五，以杞包瓜，含章，有隕自天。 象曰：九五含章，中正也。“有隕自天”，志不捨命也。”">​</a></h3><p>杞之為物，根固於下，瓜之為實，潰必自內。九五以中正剛健含章宅尊，而遇陰柔浸長之時，厚下安宅，潰亂是防，盡其人謀而聽天命者也。“以杞包瓜”，文王事紂之道，厚下以防中潰，盡人謀而聽天命者歟!</p><h3 id="上九-姤其角-吝無咎。-象曰-姤其角-上窮吝也。" tabindex="-1">上九，姤其角，吝無咎。 象曰：“姤其角”，上窮吝也。 <a class="header-anchor" href="#上九-姤其角-吝無咎。-象曰-姤其角-上窮吝也。" aria-label="Permalink to “上九，姤其角，吝無咎。 象曰：“姤其角”，上窮吝也。”">​</a></h3><p>窮不知變，吝之道也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
